  0% { opacity: 0; transform: scaleX(0.5); background-color: rgb(255, 255, 170); }
  80% { opacity: 1; transform: scaleX(1.1); }
  100% { opacity: 1; transform: scaleX(1); background-color: rgba(255, 255, 170, 0.3); }
}

